INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(14101, 'Psalms 76:8', 'Psalms', 76, 8, '&nbsp;کله چې تا د آسمان نه د اِنصاف نعره وکړه. نو زمکه ويرېدله او خاموشه شوه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14102, 'Psalms 76:9', 'Psalms', 76, 9, '&nbsp;اے پاکه خُدايه، کله چې تۀ د عدالت دپاره ودرېږې، چې د دُنيا ټول مظلومان بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14103, 'Psalms 76:10', 'Psalms', 76, 10, '&nbsp;ځکه د انسانانو غصه ستا د ثناء سبب جوړيږى، او د هغوئ د قهر نتيجه ستا د جلال باعث جوړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14104, 'Psalms 76:11', 'Psalms', 76, 11, '&nbsp;مالِک خُدائ خپل خُدائ ته منښتې ومنئ او هغه بيا ورکړئ، هغوئ ټول چې د هغۀ په خوا او شا کښې دى، او د چا نه چې يرېدل په کار دى هغۀ ته دې نذرونه ورکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14105, 'Psalms 76:12', 'Psalms', 76, 12, '&nbsp;هغه حاکمان عاجزان کوى، او د زمکې بادشاهان د هغۀ نه يره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14106, 'Psalms 77:1', 'Psalms', 77, 1, '&nbsp;ما د مدد دپاره خُدائ پاک ته ژړا وکړه، ما ژړا وکړه خُدائ پاک ته چې زما واوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14107, 'Psalms 77:2', 'Psalms', 77, 2, '&nbsp;کله چې ما باندې سخته وه مالِک خُدائ مې راياد کړے وو. ټوله شپه مې خپل لاسونه د دُعا دپاره اوچت کړى وُو. خو بيا هم زما زړۀ بې‌قراره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14108, 'Psalms 77:3', 'Psalms', 77, 3, '&nbsp;اے پاکه خُدايه، په دردونو کښې زۀ تا يادوم، او روح مې مړاوے شو او زۀ په فکر کښې ډوب شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14109, 'Psalms 77:4', 'Psalms', 77, 4, '&nbsp;ستا نه ټوله شپه سترګې پټولے نۀ شم، زۀ د ډېرې پرېشانۍ نه خبرې کولے نۀ شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14110, 'Psalms 77:5', 'Psalms', 77, 5, '&nbsp;ما په تير شوو ورځو سوچ کولو، په تېر شوو کالونو باندې مې سوچ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14111, 'Psalms 77:6', 'Psalms', 77, 6, '&nbsp;ما ټوله شپه خپل سرودونه يادول، په سوچونو کښې ډوب شوے وم او سوالونه راته پېدا شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14112, 'Psalms 77:7', 'Psalms', 77, 7, '&nbsp;”ولې مالِک خُدائ به د تل دپاره ما شړى څۀ؟ ولې هغه به بيا خپله مِهربانى ما ته نۀ ښائى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14113, 'Psalms 77:8', 'Psalms', 77, 8, '&nbsp;ولې د هغۀ نۀ ختمېدونکې مينه د تل دپاره ختمه شوه څۀ؟ ولې د هغۀ وعده د تل دپاره ناکاميابه شوه څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14114, 'Psalms 77:9', 'Psalms', 77, 9, '&nbsp;ولې خُدائ پاک مهربانى هېره کړې ده څۀ؟ ولې په غصه کښې هغۀ خپل رحم واپس کړے دے څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14115, 'Psalms 77:10', 'Psalms', 77, 10, '&nbsp;نو بيا ما خپل ځان سره ووئيل چې، ”زۀ څومره دردمند يم، چې د خُدائ تعالىٰ ښے لاس نور ما سره نۀ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14116, 'Psalms 77:11', 'Psalms', 77, 11, '&nbsp;زۀ به د مالِک خُدائ کارونه راپه ياد کړم. زۀ به ستا پخوانۍ معجزې رايادې کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14117, 'Psalms 77:12', 'Psalms', 77, 12, '&nbsp;زۀ به ستا په ټولو کارونو سوچ وکړم، او ستا په ټولو کارونو به فکر وکړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14118, 'Psalms 77:13', 'Psalms', 77, 13, '&nbsp;اے پاکه خُدايه، ستا لارې او طريقې مقدسې دى، داسې کوم يو خُدائ دے چې زمونږ خُدائ پاک ته رسى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14119, 'Psalms 77:14', 'Psalms', 77, 14, '&nbsp;تۀ هغه خُدائ پاک يې چې معجزې کوى، تۀ خپل قدرت د قومونو په مينځ کښې ښکاره کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14120, 'Psalms 77:15', 'Psalms', 77, 15, '&nbsp;په خپلو تکړه لاسونو دې خپلو خلقو ته خلاصون ورکوې، د يعقوب او د يوسف اولاد ته خلاصون ورکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14121, 'Psalms 77:16', 'Psalms', 77, 16, '&nbsp;اے پاکه خُدايه، کله چې اوبو تۀ وليدلې، نو په اوبو باندې يرې نه لړزان راغلو، او په ژورو اوبو باندې سخته يره راغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14122, 'Psalms 77:17', 'Psalms', 77, 17, '&nbsp;وريځو بارانونه راوورول، او په آسمان کښې د تندر آوازونه شول، او ستا د برېښنا غشى په کښې پړقېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14123, 'Psalms 77:18', 'Psalms', 77, 18, '&nbsp;ستا د تندر آوازونه په طوفان کښې واورېدے شول، ستا برېښنا ټوله دُنيا رڼا کړه، زمکه په لړزان او رپېدو شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14124, 'Psalms 77:19', 'Psalms', 77, 19, '&nbsp;ستا لار د سمندر په مينځ کښې ده، او په خطرناکو اوبو کښې ستا لاره ده، کۀ څۀ هم چې د پښې نښه دې نۀ ښکارېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14125, 'Psalms 77:20', 'Psalms', 77, 20, '&nbsp;تا د خپلو خلقو رهنمائى لکه د رمو وکړه، د هارون او د موسىٰ په لاس دې د هغوئ رهنمائى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14126, 'Psalms 78:1', 'Psalms', 78, 1, '&nbsp;اے زما خلقو زما تعليم ته غوږ ونيسئ، زما د خولې خبرو ته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14127, 'Psalms 78:2', 'Psalms', 78, 2, '&nbsp;زۀ به خپله خولۀ په مِثالونو پرانيزم، زۀ به زاړۀ او پټ رازونه راڅرګند کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14128, 'Psalms 78:3', 'Psalms', 78, 3, '&nbsp;مونږ چې څۀ اورېدلى او پېژندلى دى، او څۀ چې زمونږ پلار نيکۀ مونږ ته وئيلى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14129, 'Psalms 78:4', 'Psalms', 78, 4, '&nbsp;مونږ به دا د هغوئ د اولاد نه نۀ پټوُو، مونږ به دا راتلونکى نسل ته ووايو، د مالِک خُدائ د جلالى کارونو او طاقت او معجزو بيان به وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14130, 'Psalms 78:5', 'Psalms', 78, 5, '&nbsp;هغۀ خپل شريعت يعقوب ته ورکړو، او خپل اصُول يې د بنى اِسرائيلو دپاره جوړ کړل. او هغۀ زمونږ پلار نيکۀ ته حُکم وکړو، چې خپلو ماشومانو ته دې تعليم ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14131, 'Psalms 78:6', 'Psalms', 78, 6, '&nbsp;او په دې باندې به راتلونکے نسل پوهه شى، او هم هغه ماشومان چې وروستو به پېدا شى، او بيا به په خپل نمبر سره هغوئ هم خپلو ماشومانو ته ووائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14132, 'Psalms 78:7', 'Psalms', 78, 7, '&nbsp;نو بيا به دوئ په خُدائ توکل وکړى، او د هغۀ کارونه به نۀ هېروى، خو د هغۀ حُکمونه به منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14133, 'Psalms 78:8', 'Psalms', 78, 8, '&nbsp;دوئ به د خپل پلار نيکۀ په شان نۀ وى، او هغوئ به سرکشه او باغيان نۀ وى، د چا زړونه چې خُدائ پاک ته وفادار نۀ وُو، او د هغوئ احساس هم خُدائ پاک ته وفادار نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14134, 'Psalms 78:9', 'Psalms', 78, 9, '&nbsp;د اِفرائيم خلق سره د دې چې په غشو او ليندو سمبال وُو، خو بيا هم ټول د جنګ په ورځ د مېدان نه وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14135, 'Psalms 78:10', 'Psalms', 78, 10, '&nbsp;هغوئ د خُدائ پاک لوظ پوره نۀ کړو، هغوئ د هغۀ شريعت رد کړو او عمل يې پرې ونۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14136, 'Psalms 78:11', 'Psalms', 78, 11, '&nbsp;هغوئ دا هېر کړل چې هغۀ څۀ کړى وُو، هغه عجيبه کارنامې کومې چې هغۀ ورته ښودلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14137, 'Psalms 78:12', 'Psalms', 78, 12, '&nbsp;هغۀ د هغوئ د پلار نيکۀ په وړاندې معجزې وکړې، د مِصر په خاوره او د ضُعن په زمکه يې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14138, 'Psalms 78:13', 'Psalms', 78, 13, '&nbsp;سمندر يې په مينځ دوه کړو هغوئ يې ترې نه تېر کړل، او هغۀ اوبۀ د دېوال په شان ودرولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14139, 'Psalms 78:14', 'Psalms', 78, 14, '&nbsp;په ورځ کښې به هغۀ د وريځ په ذريعه رهنمائى کوله، او ټوله شپه به يې د اور په رڼا سره بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14140, 'Psalms 78:15', 'Psalms', 78, 15, '&nbsp;په بيابان کښې ورته ګټ وشلولو، او هغوئ ته لکه د سيند غوندې ډيرې اوبۀ ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14141, 'Psalms 78:16', 'Psalms', 78, 16, '&nbsp;او هغۀ د ګټ نه نِهرونه روان کړل، او اوبۀ ترې نه لکه د دريابونو روانې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14142, 'Psalms 78:17', 'Psalms', 78, 17, '&nbsp;خو بيا هم هغوئ د خُدائ خلاف ګناه کوله، او په صحرا کښې يې د خُدائ تعالىٰ خلاف سرکشى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14143, 'Psalms 78:18', 'Psalms', 78, 18, '&nbsp;دوئ قصداً د خُدائ پاک آزمېښت وکړو، او د هغۀ نه يې د خوښې خوراک وغوښتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14144, 'Psalms 78:19', 'Psalms', 78, 19, '&nbsp;هغوئ د خُدائ پاک خلاف خبرې کولې، ”خُدائ پاک په بيابان کښې د خوراک بندوبست نۀ شى کولے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14145, 'Psalms 78:20', 'Psalms', 78, 20, '&nbsp;کله چې هغۀ ګټ ووهلو نو اوبۀ ترې نه روانې شوې، او ډيرې ولې ترې نه روانې شوې، خو هغه مونږ له خوراک هم راکولے شى څۀ؟ هغه خپلو خلقو له غوښه ورکولے شى څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14146, 'Psalms 78:21', 'Psalms', 78, 21, '&nbsp;ولې کله چې مالِک خُدائ د دوئ دا خبرې واورېدې نو ډېر زيات غصه شو، او د يعقوب خلاف اور راوچت شو، او د هغۀ غضب د بنى اِسرائيلو خلاف راوچت شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14147, 'Psalms 78:22', 'Psalms', 78, 22, '&nbsp;ځکه چې په خُدائ پاک يې يقين نۀ کولو، او د هغۀ په خلاصون يې هم باور نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14148, 'Psalms 78:23', 'Psalms', 78, 23, '&nbsp;خو هغۀ بره آسمانونو ته حُکم وکړو، نو دروازې پرانستلے شوې د آسمانونو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14149, 'Psalms 78:24', 'Psalms', 78, 24, '&nbsp;او هغۀ د خوراک دپاره خلقو ته راولېږل من، هغۀ هغوئ له خوراک ورکړو د آسمان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14150, 'Psalms 78:25', 'Psalms', 78, 25, '&nbsp;انسانانو د فرښتو خوراک وخوړو. چې څومره يې خوړلے شو هغۀ دوئ ته دومره راولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14151, 'Psalms 78:26', 'Psalms', 78, 26, '&nbsp;هغۀ آسمانونو نه مشرقى هواګانې راوستلې، او هغۀ په خپل قُدرت سره جنوبى هواګانې راوستلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14152, 'Psalms 78:27', 'Psalms', 78, 27, '&nbsp;هغۀ په دوئ غوښه لکه د ګرد په شان راووروله، او مارغان يې ورته لکه د سمندر د غاړې د شګو په شان راولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14153, 'Psalms 78:28', 'Psalms', 78, 28, '&nbsp;دا مارغان يې د هغوئ د کېمپ مينځ ته راوستل، او د هغوئ د خېمو په خوا کښې کښېناستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14154, 'Psalms 78:29', 'Psalms', 78, 29, '&nbsp;دوئ ته يې دومره خوراک ورکړو چې د هغوئ نه سېوا هم شو، څۀ چې د دوئ د خوراک خواهش وو هغه هم دوئ ته ورکړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14155, 'Psalms 78:30', 'Psalms', 78, 30, '&nbsp;دوئ لا ماړۀ شوى نۀ وُو، خوراک يې لا په خولۀ کښې وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14156, 'Psalms 78:31', 'Psalms', 78, 31, '&nbsp;چې د خُدائ پاک قهر د دوئ خلاف راوچت شو. او هغۀ د دوئ نه تکړه خلق مړۀ کړل، او د بنى اِسرائيلو ځوانان يې هلاک کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14157, 'Psalms 78:32', 'Psalms', 78, 32, '&nbsp;د دې هر څۀ باوجود هغوئ بيا هم ګناه کوله، او د معجزو سره يې بيا هم ايمان نۀ ساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14158, 'Psalms 78:33', 'Psalms', 78, 33, '&nbsp;نو د هغوئ ژوند بې‌اهميته تير شو، عمر يې په يره يره تير شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14159, 'Psalms 78:34', 'Psalms', 78, 34, '&nbsp;خو کله چې خُدائ پاک د هغوئ نه ځينې هلاک کړل، نو آخر يې هم د خُدائ پاک لټون شروع کړو. هغوئ توبه وويستله او د زړۀ نه د خُدائ خواهشمند شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14160, 'Psalms 78:35', 'Psalms', 78, 35, '&nbsp;نو دوئ ته ياد شُو چې خُدائ پاک د دوئ د پناه ګټ وو، او دا چې خُدائ تعالىٰ د دوئ خلاصونکے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14161, 'Psalms 78:36', 'Psalms', 78, 36, '&nbsp;خو په خولۀ يې د هغۀ خوشامندى وکړله، او په ژبه باندې يې هغۀ ته دروغ ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14162, 'Psalms 78:37', 'Psalms', 78, 37, '&nbsp;او د دوئ زړونه هغۀ ته وفادار نۀ وُو، او دوئ د هغۀ د لوظ سره وفادار نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14163, 'Psalms 78:38', 'Psalms', 78, 38, '&nbsp;خو هغه دوئ سره ډېر مهربانه وو. د هغوئ ګناهونه يې معاف کړل او هغوئ يې تباه نۀ کړل. اکثر يې خپله غصه قابو کوله او خپل ټول قهر او غضب يې څرګند نۀ کړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14164, 'Psalms 78:39', 'Psalms', 78, 39, '&nbsp;هغۀ راياد کړل چې بنيادم خو د غوښې نه جوړ دے، د هغې هوا په شان دے چې لګى او بيا نۀ واپس کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14165, 'Psalms 78:40', 'Psalms', 78, 40, '&nbsp;څو وارې هغوئ په بيابان کښې د هغۀ خلاف بغاوت وکړو، او هغه يې په بيابان کښې خفه کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14166, 'Psalms 78:41', 'Psalms', 78, 41, '&nbsp;او په بيا بيا يې په خُدائ پاک باندې آزمېښت وکړو، دوئ د اِسرائيلو مقدس ذات خفه کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14167, 'Psalms 78:42', 'Psalms', 78, 42, '&nbsp;دوئ ته د هغۀ قدرت ياد نۀ وو، نۀ ورته دا ياد وُو چې په کومه ورځ هغۀ د ظالمانو نه خلاص کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14168, 'Psalms 78:43', 'Psalms', 78, 43, '&nbsp;هغوئ هغه معجزې رايادې نۀ کړې کومې چې په مِصر کښې شوې وې، او نۀ هغه عجيبه کارنامې چې په ضُعن کښې شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14169, 'Psalms 78:44', 'Psalms', 78, 44, '&nbsp;هغۀ د دوئ سيندونه په وينو بدل کړل، دوئ د خپلو نِهرونو اوبۀ څښلے نۀ شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14170, 'Psalms 78:45', 'Psalms', 78, 45, '&nbsp;هغۀ دوئ پسې د مچانو لښکر راولېږلو چې دوئ تباه کړى، او د چيندخانو عذاب چې دوئ ته تکليف ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14171, 'Psalms 78:46', 'Psalms', 78, 46, '&nbsp;هغۀ د دوئ فصلونه مُلخانو ته حواله کړل، او د هغوئ غله دانه قحطى مُلخانو وخوړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14172, 'Psalms 78:47', 'Psalms', 78, 47, '&nbsp;هغۀ د دوئ د انګورو باغونه په ږلۍ سره تباه کړل، او د دوئ اينځران يې ټول ږلۍ سره تباه کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14173, 'Psalms 78:48', 'Psalms', 78, 48, '&nbsp;او هغۀ د دوئ څاروى ږلۍ ته حواله کړل، او د دوئ رَمې يې د برېښنا غشو ته حواله کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14174, 'Psalms 78:49', 'Psalms', 78, 49, '&nbsp;هغۀ دوئ ته خپله سخته غصه وښودله، او خپل غضب او قهر يې ورته وښودلو، او د هلاکونکو فرښتو دسته يې راولېږله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14175, 'Psalms 78:50', 'Psalms', 78, 50, '&nbsp;هغۀ خپلې غصې ته لار جوړه کړه، او هغۀ دوئ د مرګ نه بچ نۀ کړل، خو دوئ يې وبا ته په حواله کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14176, 'Psalms 78:51', 'Psalms', 78, 51, '&nbsp;هغۀ د مِصريانو ټول مشران زامن مړۀ کړل، د حام په خېمو کښې يې د هغوئ د نارينتوب وړومبۍ مېوه ختمه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14177, 'Psalms 78:52', 'Psalms', 78, 52, '&nbsp;خو هغۀ خپل خلق لکه د رمو په شان ترې نه بهر راوويستل، او د ګډو په شان يې په بيابان کښې د هغوئ لارښودنه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14178, 'Psalms 78:53', 'Psalms', 78, 53, '&nbsp;چې دوئ ونۀ يريږى نو هغۀ ورته پر امن لار وښودله، خو سمندر د دوئ دشمنان غرق کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14179, 'Psalms 78:54', 'Psalms', 78, 54, '&nbsp;نو وروستو يې هغوئ د خپل مقدس مُلک سرحد ته راوستل، هغه غريزه مُلک ته چې هغۀ په خپل قدرت سره قبضه کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14180, 'Psalms 78:55', 'Psalms', 78, 55, '&nbsp;د دوئ نه وړاندې‎ هغۀ د هغې مُلک نه خلق وشړل، او په ميراث کښې د هغوئ زمکې دوئ ته حواله کړې او هغۀ د بنى اِسرائيلو ټولې قبيلې د دوئ په کورنو کښې سمبالې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14181, 'Psalms 78:56', 'Psalms', 78, 56, '&nbsp;خو هغوئ په مالِک خُدائ باندې آزمېښت وکړلو، او د خُدائ تعالىٰ خلاف يې سرکشى وکړه او دوئ د هغۀ د حُکمونو خيال ونۀ ساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14182, 'Psalms 78:57', 'Psalms', 78, 57, '&nbsp;هغوئ د خپل ‎پلار نيکۀ غوندې بې‌وفا او بې‌ايمانه وُو، لکه د خرابې ليندې په شان نا باوره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14183, 'Psalms 78:58', 'Psalms', 78, 58, '&nbsp;دوئ هغه په بُت‌خانو جوړولو باندې غصه کړلو، او هغوئ د هغۀ غېرت د دوئ د بُتانو په خلاف راوپارولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14184, 'Psalms 78:59', 'Psalms', 78, 59, '&nbsp;کله چې خُدائ پاک د دوئ نه خبر شو نو هغه ډېر په قهر شو، او هغۀ اِسرائيل په مکمل طور رد کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14185, 'Psalms 78:60', 'Psalms', 78, 60, '&nbsp;او هغۀ د سيلا پاکه خېمه پرېښوده، کومه خېمه چې هغۀ د بنيادمو مينځ کښې لګولې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14186, 'Psalms 78:61', 'Psalms', 78, 61, '&nbsp;او هغۀ خپل د لوظ صندوق نورو ته حواله کړو، او خپل شان و شوکت يې دشمنانو ته حواله کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14187, 'Psalms 78:62', 'Psalms', 78, 62, '&nbsp;هغۀ خپل خلق د تُورې خولې ته ورکړل، او خپل منتخب شوى قوم ته هغه ډېر غصه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14188, 'Psalms 78:63', 'Psalms', 78, 63, '&nbsp;په اور يې د هغوئ ځوانان تباه کړل، او پېغلو يې سندرې د وادۀ وانۀ ورېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14189, 'Psalms 78:64', 'Psalms', 78, 64, '&nbsp;د دوئ اِمامان يې په تُوره ووژل، او د دوئ کونډو ماتم ونۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14190, 'Psalms 78:65', 'Psalms', 78, 65, '&nbsp;مالِک راپاڅېدو لکه څنګه چې څوک د خوب نه راويښ شى، لکه څنګه چې بنيادم د شرابو په نشه مست شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14191, 'Psalms 78:66', 'Psalms', 78, 66, '&nbsp;هغۀ خپل دشمنان په شا وتنبول، او هغه يې د تل دپاره په شرمونو وشرمول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14192, 'Psalms 78:67', 'Psalms', 78, 67, '&nbsp;هغۀ د يوسف اولاد رد کړو، او هغۀ د اِفرائيم قبيله غوره نۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14193, 'Psalms 78:68', 'Psalms', 78, 68, '&nbsp;خو هغۀ د يهوداه قبيله غوره کړه، او د صيون غر چې زياته مينه يې ورسره وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14194, 'Psalms 78:69', 'Psalms', 78, 69, '&nbsp;هغۀ هلته خپل مقدس ځائ لکه د لوړو آسمانونو په شان جوړ کړو، او لکه د هغه زمکې په شان چې د تل دپاره يې قائمه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14195, 'Psalms 78:70', 'Psalms', 78, 70, '&nbsp;هغۀ د خپل خِدمت دپاره داؤد منتخب کړو، او هغه يې د ګډو د شپول نه راوچت کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14196, 'Psalms 78:71', 'Psalms', 78, 71, '&nbsp;د ګډو د شپونتوب نه يې هغه راوستلو، چې شپون شى د يعقوب د خپلو خلقو، د خپل غوره شوى قوم اِسرائيلو شپونتوب يې پرې وکړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14197, 'Psalms 78:72', 'Psalms', 78, 72, '&nbsp;او داؤد په پوره زړۀ سره د دوئ شپونتوب وکړو، او په عقلمندۍ سره يې د هغوئ لارښودنه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14198, 'Psalms 79:1', 'Psalms', 79, 1, '&nbsp;اے پاکه خُدايه غېر قومونو ستا مُلک قبضه کړے دے، هغوئ ستا د مقدس کور بې‌حرمتى وکړه او هغوئ يروشلم په کنډرو بدل کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14199, 'Psalms 79:2', 'Psalms', 79, 2, '&nbsp;هغوئ ستا د خادِمانو لاشونه د هوا مارغانو ته وغورزول، او ستا د مقدسينو غوښې يې ځنګلى ځناورو ته واچولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14200, 'Psalms 79:3', 'Psalms', 79, 3, '&nbsp;هغوئ د دوئ وينه د يروشلم په کوڅو کښې لکه د اوبو توئ کړه، او داسې څوک نشته چې د دوئ مړى ښخ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');